/* Stratova brand workspace pages */
'use strict';

const FOLLOW_DAYS = 30;
const staffName = (d, id) => (d.staff.find(x => x.id === id) || {}).name || '';

/* ---------- shared: invoices ---------- */
function salesTable(list, { brand = false } = {}) {
  if (!list.length) return empty('list', 'No invoices found', 'Try changing the filters or create a new bill.');
  return `<div class="tw"><table><thead><tr><th>Invoice</th>${brand ? '<th>Brand</th>' : ''}<th>Date</th><th>Vehicle</th><th>Customer</th><th class="r">Total</th><th class="r">Balance</th><th>Payment</th><th>Job</th><th></th></tr></thead><tbody>
  ${list.map(({ s, b }) => `<tr class="click" onclick="viewSale('${s.id}','${b}')"><td><b>${inv(s.no)}</b></td>${brand ? `<td>${brandDot(b)}</td>` : ''}<td class="nowrap">${nice(s.date)}</td>
  <td><b>${esc(s.car)}</b><small>${esc(s.model)}</small></td><td>${esc(s.name) || '—'}<small>${esc(s.phone)}</small></td>
  <td class="r">${money(sTotal(s))}</td><td class="r" style="color:${sBal(s) > 0 ? 'var(--warn)' : 'inherit'}">${money(Math.max(0, sBal(s)))}</td><td>${payChip(s)}</td><td>${jobChip(s.status)}</td>
  <td class="nowrap r"><button class="btn ghost sm icon" title="Print" onclick="event.stopPropagation();printInvoice('${s.id}','${b}')">${ic('print', 15)}</button>
  ${sBal(s) > 0 ? ` <button class="btn sm" onclick="event.stopPropagation();payModal('${s.id}','${b}')">Receive</button>` : ''}</td></tr>`).join('')}</tbody></table></div>`;
}

function printHTML(html, paper = 'A4') {
  $('#pageStyle').textContent = paper === 'thermal' ? '@page{size:80mm auto;margin:3mm}' : '@page{size:A4;margin:10mm}';
  $('#printArea').innerHTML = html; setTimeout(() => window.print(), 200);
}
function printInvoice(id, b) {
  if (b) S.B = b;
  const d = D(), Br = BRANDS[S.B], s = d.sales.find(x => x.id === id), p = d.profile, tot = sTotal(s), paid = sPaid(s), bal = sBal(s);
  printHTML(`<div class="inv ${p.paper === 'thermal' ? 'thermal' : ''}" style="--ib:${Br.color}"><div class="band"></div><div class="in">
    <div class="hd"><div style="display:flex;align-items:center"><img src="${Br.logo}" alt=""><div class="co"><b>${Br.name}</b>${esc(p.phone)}<br>${esc(p.address)}</div></div>
      <div class="ttl"><h1>INVOICE</h1><div style="font-size:13px;margin-top:6px"><b>${inv(s.no)}</b><br>${nice(s.date)}</div></div></div>
    <div class="boxes"><div><small>Billed to</small><b>${esc(s.name) || 'Walk-in customer'}</b><br>${esc(s.phone)}</div>
      <div><small>Vehicle</small><b>${esc(s.car)}</b><br>${esc(s.model)}</div>
      <div><small>Payment</small>${bal <= 0 ? '<b style="color:#0a8a47">Paid in full</b>' : paid > 0 ? '<b style="color:#c47a00">Partially paid</b>' : '<b style="color:#c0172b">Unpaid</b>'}<br>${esc((s.payments[0] || {}).method || '')}</div></div>
    <table><thead><tr><th style="width:36px">#</th><th>Description</th><th style="text-align:right;width:130px">Amount</th></tr></thead><tbody>
      ${s.items.map((i, n) => `<tr><td>${n + 1}</td><td>${esc(i.desc)}</td><td style="text-align:right">${money(i.price)}</td></tr>`).join('')}</tbody></table>
    <div class="tt"><div><span>Subtotal</span><span>${money(sSub(s))}</span></div>
      ${s.discount ? `<div><span>Discount</span><span>- ${money(s.discount)}</span></div>` : ''}
      ${s.taxPct ? `<div><span>Tax (${s.taxPct}%)</span><span>${money(sTax(s))}</span></div>` : ''}
      <div class="g"><span>Total</span><span>${money(tot)}</span></div>
      ${paid > 0 ? `<div><span>Paid / Advance</span><span>${money(paid)}</span></div>` : ''}
      <div class="${bal > 0 ? 'd' : ''}"><span>Balance due</span><span>${money(Math.max(0, bal))}</span></div></div>
    ${bal <= 0 ? '<div class="stamp">PAID</div>' : ''}
    ${s.note ? `<p style="font-size:13px"><b>Note:</b> ${esc(s.note)}</p>` : ''}
    <div class="sign"><div>Customer signature</div><div>Authorized signature</div></div>
    <div class="ft">${esc(p.footer)}<small>Generated by Stratova</small></div></div></div>`, p.paper);
}
function viewSale(id, b) {
  if (b) S.B = b;
  const d = D(), s = d.sales.find(x => x.id === id); if (!s) return;
  const waText = `Hello ${s.name || ''}, thank you for choosing ${BRANDS[S.B].name}.\n${inv(s.no)} (${s.car})\nTotal: ${money(sTotal(s))}\nPaid: ${money(sPaid(s))}\nRemaining: ${money(Math.max(0, sBal(s)))}`;
  modal(`<div class="mh"><div><h2>${inv(s.no)} · ${esc(s.car)}</h2><div class="muted">${nice(s.date)} · ${esc(s.name) || 'Walk-in'} ${esc(s.phone)} · ${esc(s.model)}</div>
    <div style="margin-top:8px;display:flex;gap:8px;align-items:center">${payChip(s)} ${jobChip(s.status)}${s.staff ? `<span class="muted">· ${esc(staffName(d, s.staff))}</span>` : ''}</div></div><button class="x" onclick="closeModal()">${ic('x')}</button></div>
    <div class="tw"><table><thead><tr><th>Item</th><th class="r">Price</th><th class="r">Product 🔒</th><th class="r">Labour 🔒</th></tr></thead><tbody>
    ${s.items.map(i => `<tr><td>${esc(i.desc)}</td><td class="r">${money(i.price)}</td><td class="r">${money(i.prod)}</td><td class="r">${money(i.lab)}</td></tr>`).join('')}</tbody></table></div>
    <div class="row" style="margin-top:14px;align-items:flex-start"><div><h3 style="margin-bottom:6px">Payments</h3>
      ${s.payments.length ? s.payments.map(p => `<div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--line)"><span>${nice(p.date)} · ${esc(p.method)}${p.note ? ' · ' + esc(p.note) : ''}</span><b>${money(p.amount)}</b></div>`).join('') : '<div class="muted">No payments received yet</div>'}</div>
    <div class="tot"><div><span>Discount</span><span>${money(s.discount || 0)}</span></div>${s.taxPct ? `<div><span>Tax (${s.taxPct}%)</span><span>${money(sTax(s))}</span></div>` : ''}
      <div class="big"><span>Total</span><span>${money(sTotal(s))}</span></div><div><span>Paid</span><span>${money(sPaid(s))}</span></div>
      <div class="rem"><span>Remaining</span><span>${money(Math.max(0, sBal(s)))}</span></div>
      <div class="internal"><div class="hint">🔒 Private</div><div><span>Product + labour cost</span><span>${money(sProd(s) + sLab(s))}</span></div><div><b>Profit</b><b style="color:var(--good)">${money(sProfit(s))}</b></div></div></div></div>
    <div class="mf" style="justify-content:space-between"><div style="display:flex;gap:8px"><button class="btn danger" onclick="delSale('${s.id}')">${ic('trash', 15)} Delete</button>
      <select id="vsStatus" style="width:auto">${opts(STATUSES, s.status)}</select></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn ghost" id="vsWA">${ic('phone', 15)} WhatsApp</button>
      ${sBal(s) > 0 ? `<button class="btn soft" onclick="payModal('${s.id}')">Receive payment</button>` : ''}<button class="btn" onclick="closeModal();printInvoice('${s.id}')">${ic('print', 15)} Print</button></div></div>`);
  $('#vsStatus').onchange = e => { s.status = e.target.value; logAct(`${inv(s.no)} moved to ${s.status}`); save(); toast('Job status updated'); refresh(); };
  $('#vsWA').onclick = () => openWA(s.phone, waText);
}
function payModal(id, b) {
  if (b) S.B = b;
  const s = D().sales.find(x => x.id === id);
  formModal({
    title: 'Receive payment', sub: `${inv(s.no)} · ${esc(s.car)} · Balance <b style="color:var(--warn)">${money(sBal(s))}</b>`,
    fields: [{ k: 'amount', label: 'Amount (Rs)', type: 'number', req: true, pos: true, def: sBal(s) }, { k: 'method', label: 'Method', type: 'select', options: PAY }, { k: 'date', label: 'Date', type: 'date', def: today() }],
    values: { amount: sBal(s) }, saveLabel: 'Save payment',
    onSave: o => {
      if (o.amount > sBal(s) + .01) { toast('Amount is more than the balance', 'err'); return false; }
      s.payments.push({ date: o.date || today(), amount: o.amount, method: o.method, note: 'Payment' }); logAct(`Received ${money(o.amount)} on ${inv(s.no)}`); save(); toast('Payment recorded'); refresh();
    }
  });
}
function delSale(id) {
  confirmBox('This invoice and its payment history will be permanently deleted.', () => { const d = D(); d.sales = d.sales.filter(s => s.id !== id); save(); toast('Invoice deleted'); refresh(); });
}

/* ---------- customers (cars) ---------- */
function carGroupsFrom(list) {
  const m = {};
  list.forEach(({ s, b }) => { const k = plate(s.car); if (!k) return; (m[k] = m[k] || { key: k, sales: [] }).sales.push({ s, b }); });
  return Object.values(m).map(g => {
    g.sales.sort((a, b) => a.s.date < b.s.date || (a.s.date === b.s.date && a.s.no < b.s.no) ? 1 : -1); const l = g.sales[0];
    return { ...g, car: l.s.car, name: l.s.name, phone: l.s.phone, model: l.s.model, visits: g.sales.length, brands: [...new Set(g.sales.map(x => x.b))],
      spent: sum(g.sales, x => sTotal(x.s)), bal: sum(g.sales, x => Math.max(0, sBal(x.s))), last: l.s.date };
  }).sort((a, b) => a.last < b.last ? 1 : -1);
}
function carHistory(key) {
  const g = carGroupsFrom(allSales()).find(x => x.key === key); if (!g) return;
  modal(`<div class="mh"><div><h2>${esc(g.car)} <span class="muted" style="font-size:14px;font-weight:500">${esc(g.model)}</span></h2><div class="muted">${esc(g.name) || '—'} · ${esc(g.phone)}</div></div><button class="x" onclick="closeModal()">${ic('x')}</button></div>
  <div class="grid" style="grid-template-columns:repeat(3,1fr);margin-bottom:14px">${kpi('Visits', g.visits, { icon: 'car' })}${kpi('Total spent', money(g.spent), { icon: 'cash', tone: 'good' })}${kpi('Balance due', money(g.bal), { icon: 'wallet', tone: g.bal ? 'warn' : '' })}</div>
  <div class="tw"><table><thead><tr><th>Invoice</th><th>Date</th><th>Services</th><th class="r">Total</th><th>Payment</th></tr></thead><tbody>
  ${g.sales.map(({ s, b }) => `<tr class="click" onclick="viewSale('${s.id}','${b}')"><td>${inv(s.no)}${S.mode === 'admin' ? `<small>${BRANDS[b].short}</small>` : ''}</td><td>${nice(s.date)}</td><td>${esc(s.items.map(i => i.desc).join(', '))}</td><td class="r">${money(sTotal(s))}</td><td>${payChip(s)}</td></tr>`).join('')}</tbody></table></div>
  <div class="mf"><button class="btn ghost" onclick="closeModal()">Close</button></div>`);
}
function customersTable(groups, brand = false) {
  if (!groups.length) return empty('car', 'No vehicles found', 'Vehicles appear here automatically after your first bill.');
  const stale = today(), cutoff = addDays(stale, -FOLLOW_DAYS);
  return `<div class="tw"><table><thead><tr><th>Vehicle</th><th>Customer</th>${brand ? '<th>Brand</th>' : ''}<th class="r">Visits</th><th>Last visit</th><th class="r">Total spent</th><th class="r">Balance</th><th></th></tr></thead><tbody>
  ${groups.map(g => `<tr class="click" onclick="carHistory('${g.key}')"><td><b>${esc(g.car)}</b><small>${esc(g.model)}</small></td><td>${esc(g.name) || '—'}<small>${esc(g.phone)}</small></td>
  ${brand ? `<td>${g.brands.map(brandDot).join('<br>')}</td>` : ''}<td class="r">${g.visits}</td><td class="nowrap">${nice(g.last)} ${g.last < cutoff ? '<span class="chip low">Due</span>' : ''}</td>
  <td class="r">${money(g.spent)}</td><td class="r" style="color:${g.bal ? 'var(--warn)' : 'inherit'}">${money(g.bal)}</td>
  <td class="nowrap r"><button class="btn ghost sm icon" title="WhatsApp reminder" onclick="event.stopPropagation();remind('${g.key}')">${ic('phone', 15)}</button></td></tr>`).join('')}</tbody></table></div>`;
}
function remind(key) {
  const g = carGroupsFrom(allSales()).find(x => x.key === key), br = S.mode === 'admin' ? BRANDS[g.brands[0]].name : BRANDS[S.B].name;
  openWA(g.phone, g.bal > 0 ? `Hello ${g.name || ''}, a gentle reminder from ${br}: a balance of ${money(g.bal)} is pending for ${g.car}. Thank you!`
    : `Hello ${g.name || ''}, this is ${br}. It has been a while since your last visit for ${g.car}. Book your next detailing/service with us and enjoy a special offer!`);
}

/* ================= DASHBOARD ================= */
PAGES.dashboard = () => {
  const d = D(), t = today(), y = addDays(t, -1), T = stats(d, t, t), Y = stats(d, y, y), ms = monthStart(t), M = stats(d, ms, t);
  const pf = monthStart(addDays(ms, -1)), PM = stats(d, pf, addDays(pf, daysBetween(ms, t) - 1));
  const out = sum(d.sales, s => Math.max(0, sBal(s))), bk = buckets(d, 'daily', t), mon = buckets(d, 'monthly', t).slice(-6);
  const studio = d.sales.filter(s => s.status !== 'Delivered').sort((a, b) => a.date < b.date ? 1 : -1);
  const pend = d.sales.filter(s => sBal(s) > 0).sort((a, b) => a.date < b.date ? -1 : 1).slice(0, 6);
  const recent = [...d.sales].reverse().slice(0, 7).map(s => ({ s, b: S.B })), low = d.products.filter(p => p.qty <= p.min);
  const todayBk = d.bookings.filter(b => b.date === t && b.status === 'Scheduled');
  const jobs = STATUSES.map(st => [st, d.sales.filter(s => s.status === st && (st !== 'Delivered' || s.date === t)).length]);
  const mo = {}; d.sales.filter(s => s.date >= ms).forEach(s => s.items.forEach(i => { const k = i.desc || '—'; mo[k] = (mo[k] || 0) + i.price; }));
  const top = Object.entries(mo).sort((a, b) => b[1] - a[1]).slice(0, 5), topMax = top.length ? top[0][1] : 1;
  const hr = new Date().getHours(), greet = hr < 12 ? 'Good morning' : hr < 18 ? 'Good afternoon' : 'Good evening';
  const sp = k => bk.map(b => b.s[k]);
  $('#view').innerHTML = phead(greet, `${new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}`,
    `<button class="btn ghost" onclick="go('bookings')">${ic('calendar', 16)} Appointments</button><button class="btn ghost" onclick="go('expenses')">${ic('wallet', 16)} Add expense</button><button class="btn" onclick="go('billing')">${ic('plus', 16)} New bill</button>`) + `
  <div class="hero"><img class="wm" src="${BRANDS[S.B].logo}" alt="">
    <div class="hl"><div class="eyebrow">Today's revenue</div><div class="hbig">${money(T.revenue)}</div>
      <div class="hsub">${dchip(pct(T.revenue, Y.revenue))}<span>vs yesterday · ${T.count} bill${T.count === 1 ? '' : 's'}</span></div>
      <div class="hstats"><div><small>Cash collected</small><b class="g">${money(T.cash)}</b></div><div><small>Expenses</small><b class="b">${money(T.exp)}</b></div><div><small>Net profit</small><b class="${T.net >= 0 ? 'g' : 'b'}">${money(T.net)}</b></div></div></div>
    <div class="hr"><div class="ch"><h3>Revenue · last 14 days</h3><span class="muted">${money(sum(bk, b => b.s.revenue))} total</span></div>${areaSvg(bk.map(b => b.l), sp('revenue'))}</div></div>
  ${studio.length ? `<div class="strip-h"><h3>Now in studio</h3><span class="chip InProgress">${studio.length} car${studio.length > 1 ? 's' : ''}</span></div><div class="strip">${studio.slice(0, 10).map(s => `<div class="scar" onclick="viewSale('${s.id}')"><div><b>${esc(s.car)}</b><small>${esc(s.model) || '—'}</small></div><div class="r">${jobChip(s.status)}<small>${sBal(s) > 0 ? money(sBal(s)) + ' due' : 'Paid'}</small></div></div>`).join('')}</div>` : ''}
  <div class="grid k4" style="margin-top:6px">
    ${kpi('Revenue · this month', money(M.revenue), { icon: 'trend', delta: pct(M.revenue, PM.revenue), sub: 'vs same days last month', spark: sp('revenue') })}
    ${kpi('Net profit · this month', money(M.net), { icon: 'chart', tone: M.net >= 0 ? 'good' : 'bad', delta: pct(M.net, PM.net), sub: M.margin.toFixed(0) + '% margin', spark: sp('net') })}
    ${kpi('Expenses · this month', money(M.exp), { icon: 'wallet', tone: 'bad', delta: pct(M.exp, PM.exp), sub: 'vs same days last month', spark: sp('exp') })}
    ${kpi('Collected · this month', money(M.cash), { icon: 'cash', tone: 'good', sub: (M.revenue ? Math.round(M.cash / M.revenue * 100) : 0) + '% of billed amount', spark: sp('cash') })}
    ${kpi('Outstanding balance', money(out), { icon: 'alert', tone: 'warn', sub: d.sales.filter(s => sBal(s) > 0).length + ' open invoices' })}
    ${kpi('Cars in studio', studio.length, { icon: 'car', tone: 'info', sub: 'not yet delivered' })}
    ${kpi('Average bill', money(M.count ? M.revenue / M.count : 0), { icon: 'bill', sub: 'this month' })}
    ${kpi('Bills this month', M.count, { icon: 'list', sub: PM.count + ' in same days last month' })}
  </div>
  <div class="cols"><div class="card"><div class="ch"><h3>Revenue & profit · last 6 months</h3>${legend([{ name: 'Revenue', color: 'var(--accent)' }, { name: 'Net profit', color: '#2fd08a' }])}</div>
    ${barSvg(mon.map(b => b.l), [{ name: 'Revenue', color: 'var(--accent)', data: mon.map(b => b.s.revenue) }, { name: 'Net profit', color: '#2fd08a', data: mon.map(b => b.s.net) }], 250)}</div>
    <div class="stack"><div class="card"><div class="ch"><h3>Job pipeline</h3><button class="btn ghost sm" onclick="go('jobs')">Open board</button></div>
      ${jobs.map(([st, n]) => `<div style="display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-bottom:1px solid var(--line)">${jobChip(st)}<b>${n}</b></div>`).join('')}</div>
    <div class="card"><div class="ch"><h3>Today's appointments</h3><button class="btn ghost sm" onclick="go('bookings')">View all</button></div>
      ${todayBk.length ? `<div class="list">${todayBk.slice(0, 4).map(b => `<div><span><b>${esc(b.time)}</b> · ${esc(b.car)}<small>${esc(b.service)}</small></span></div>`).join('')}</div>` : '<div class="muted">No appointments scheduled for today.</div>'}</div></div></div>
  <div class="cols eq3">
    <div class="card"><div class="ch"><h3>Pending payments</h3></div>${pend.length ? `<div class="list">${pend.map(s => `<div><span><b>${esc(s.car)}</b><small>${esc(s.name)} · ${nice(s.date)}</small></span><span style="display:flex;gap:8px;align-items:center"><b style="color:var(--warn)">${money(sBal(s))}</b><button class="btn sm" onclick="payModal('${s.id}')">Receive</button></span></div>`).join('')}</div>` : empty('check', 'All clear', 'No outstanding balances.')}</div>
    <div class="card"><div class="ch"><h3>Top services · this month</h3></div>${top.length ? `<div class="list">${top.map(([k, v]) => `<div style="display:block"><div style="display:flex;justify-content:space-between"><span>${esc(k)}</span><b>${money(v)}</b></div><div class="bar" style="margin-top:6px"><i style="width:${v / topMax * 100}%;background:linear-gradient(90deg,var(--accent),var(--accent2))"></i></div></div>`).join('')}</div>` : '<div class="muted">No sales this month yet.</div>'}</div>
    <div class="card"><div class="ch"><h3>Low stock alerts</h3><button class="btn ghost sm" onclick="go('inventory')">Inventory</button></div>${low.length ? `<div class="list">${low.slice(0, 6).map(p => `<div><span>${esc(p.name)}</span><span class="chip low">${p.qty} ${esc(p.unit)} left</span></div>`).join('')}</div>` : '<div class="muted">All products are sufficiently stocked.</div>'}</div>
  </div>
  <div class="card" style="margin-top:14px"><div class="ch"><h3>Recent invoices</h3><button class="btn ghost sm" onclick="go('invoices')">View all</button></div>${salesTable(recent)}</div>`;
};

/* ================= BILLING ================= */
let draft = null;
const newDraft = () => ({ car: '', name: '', phone: '', model: '', date: today(), items: [{ desc: '', price: 0, prod: 0, lab: 0 }], discount: 0, advance: 0, method: 'Cash', note: '', staff: '', status: 'In Progress', taxPct: D().profile.tax || 0, booking: '' });

PAGES.billing = () => {
  draft = draft || newDraft(); const d = D();
  $('#view').innerHTML = phead('New Bill', 'Create an invoice, record the advance and track your private costs', `<button class="btn ghost" id="bClear">Clear form</button>`) + `
  <div class="bill"><div class="stack">
    <div class="card"><h3>Customer & vehicle</h3><div class="fgrid">
      <div><label>Car number *</label><input id="fCar" placeholder="LEA-1234" style="text-transform:uppercase" value="${esc(draft.car)}"></div>
      <div><label>Car model / colour</label><input id="fModel" placeholder="Honda Civic 2021 – White" value="${esc(draft.model)}"></div>
      <div><label>Customer name</label><input id="fName" value="${esc(draft.name)}"></div>
      <div><label>Phone</label><input id="fPhone" placeholder="03xx xxxxxxx" value="${esc(draft.phone)}"></div>
      <div><label>Date</label><input id="fDate" type="date" value="${draft.date}"></div>
      <div><label>Assigned to</label><select id="fStaff"><option value="">— Unassigned —</option>${d.staff.map(s => `<option value="${s.id}" ${s.id === draft.staff ? 'selected' : ''}>${esc(s.name)}</option>`).join('')}</select></div></div>
      <div id="carHint" class="hint" style="margin-top:10px"></div></div>
    <div class="card"><div class="ch"><h3>Services & items</h3><span class="hint">🔒 Cost columns are private and never printed</span></div>
      <div class="qs">${d.services.map(sv => `<button data-sv="${sv.id}" title="${sv.price ? 'Usually ' + money(sv.price) : ''}">+ ${esc(sv.name)}</button>`).join('') || '<span class="muted">Add services in Service Catalog for one-click lines.</span>'}</div>
      <div class="tw"><table class="lines"><thead><tr><th>Description</th><th style="width:120px">Price</th><th class="int" style="width:120px">Product cost 🔒</th><th class="int" style="width:120px">Labour cost 🔒</th><th style="width:44px"></th></tr></thead><tbody id="lines"></tbody></table></div>
      <datalist id="svl">${d.services.map(s => `<option value="${esc(s.name)}">`).join('')}</datalist>
      <button class="btn ghost sm" id="addLine" style="margin-top:10px">${ic('plus', 14)} Add line</button></div>
    <div class="card"><h3>Notes</h3><input id="fNote" placeholder="Printed on the invoice (e.g. warranty, next service date)" value="${esc(draft.note)}"></div></div>
    <div class="card sticky"><h3>Summary</h3>
      <div class="fgrid" style="margin-bottom:12px"><div><label>Discount (Rs)</label><input id="fDisc" type="number" min="0" value="${draft.discount || ''}"></div><div><label>Tax %</label><input id="fTax" type="number" min="0" step="any" value="${draft.taxPct || ''}"></div>
        <div><label>Advance received (Rs)</label><input id="fAdv" type="number" min="0" value="${draft.advance || ''}"></div><div><label>Payment method</label><select id="fMethod">${opts(PAY, draft.method)}</select></div>
        <div class="wide"><label>Job status</label><select id="fStatus">${opts(STATUSES, draft.status)}</select></div></div>
      <div class="tot" id="totals"></div><div class="internal" id="internal"></div>
      <div style="display:grid;gap:8px;margin-top:16px"><button class="btn" id="savePrint">${ic('print', 16)} Save & print bill</button><button class="btn ghost" id="saveOnly">Save only</button></div></div></div>`;
  renderLines(); recalc();
  $('#addLine').onclick = () => { readForm(); draft.items.push({ desc: '', price: 0, prod: 0, lab: 0 }); renderLines(); };
  $('#bClear').onclick = () => { draft = newDraft(); PAGES.billing(); };
  $('#saveOnly').onclick = () => saveSale(false); $('#savePrint').onclick = () => saveSale(true);
  $$('.qs button').forEach(b => b.onclick = () => {
    readForm(); const sv = d.services.find(x => x.id === b.dataset.sv), it = { desc: sv.name, price: 0, prod: 0, lab: 0, hint: sv };
    const last = draft.items[draft.items.length - 1]; if (last && !last.desc && !last.price) draft.items[draft.items.length - 1] = it; else draft.items.push(it);
    renderLines(); recalc(); const pi = $$('#lines tr')[draft.items.indexOf(it)]?.querySelector('[data-f=price]'); if (pi) pi.focus();
  });
  ['fDisc', 'fAdv', 'fTax', 'fMethod', 'fStatus', 'fStaff'].forEach(i => $('#' + i).oninput = recalc);
  $('#fCar').oninput = carLookup; carLookup();
};
function renderLines() {
  $('#lines').innerHTML = draft.items.map((it, i) => `<tr>
    <td><input data-i="${i}" data-f="desc" list="svl" value="${esc(it.desc)}" placeholder="Service / item"></td>
    <td><input data-i="${i}" data-f="price" type="number" min="0" value="${it.price || ''}" placeholder="${it.hint && it.hint.price ? 'usually ' + it.hint.price : 'Enter price'}"></td>
    <td class="int"><input data-i="${i}" data-f="prod" type="number" min="0" value="${it.prod || ''}" placeholder="${it.hint && it.hint.prod ? 'usually ' + it.hint.prod : ''}"></td>
    <td class="int"><input data-i="${i}" data-f="lab" type="number" min="0" value="${it.lab || ''}" placeholder="${it.hint && it.hint.lab ? 'usually ' + it.hint.lab : ''}"></td>
    <td><button class="btn danger sm icon" data-del="${i}" title="Remove">${ic('x', 14)}</button></td></tr>`).join('');
  $$('#lines input').forEach(inp => {
    inp.oninput = () => { readForm(); recalc(); };
    if (inp.dataset.f === 'desc') inp.onchange = () => {
      const sv = D().services.find(x => x.name.toLowerCase() === inp.value.trim().toLowerCase()), it = draft.items[+inp.dataset.i];
      if (sv && !it.price) { it.hint = sv; renderLines(); recalc(); }
    };
  });
  $$('#lines [data-del]').forEach(b => b.onclick = () => { readForm(); if (draft.items.length > 1) draft.items.splice(+b.dataset.del, 1); renderLines(); recalc(); });
}
function readForm() {
  draft.car = $('#fCar').value.trim().toUpperCase(); draft.name = $('#fName').value.trim(); draft.phone = $('#fPhone').value.trim(); draft.model = $('#fModel').value.trim();
  draft.date = $('#fDate').value || today(); draft.discount = num($('#fDisc').value); draft.advance = num($('#fAdv').value); draft.taxPct = num($('#fTax').value);
  draft.method = $('#fMethod').value; draft.status = $('#fStatus').value; draft.staff = $('#fStaff').value; draft.note = $('#fNote').value.trim();
  $$('#lines input').forEach(inp => { const it = draft.items[+inp.dataset.i], f = inp.dataset.f; it[f] = f === 'desc' ? inp.value : num(inp.value); });
}
function recalc() {
  readForm(); const tmp = { items: draft.items, discount: draft.discount, taxPct: draft.taxPct };
  const tot = sTotal(tmp), rem = tot - draft.advance, prod = sProd(tmp), lab = sLab(tmp), prof = sNet(tmp) - prod - lab;
  $('#totals').innerHTML = `<div><span>Subtotal</span><span>${money(sSub(tmp))}</span></div><div><span>Discount</span><span>- ${money(draft.discount)}</span></div>
    ${draft.taxPct ? `<div><span>Tax (${draft.taxPct}%)</span><span>${money(sTax(tmp))}</span></div>` : ''}
    <div class="big"><span>Total</span><span>${money(tot)}</span></div><div><span>Advance received</span><span>${money(draft.advance)}</span></div>
    <div class="big rem"><span>Remaining</span><span>${money(Math.max(0, rem))}</span></div>`;
  $('#internal').innerHTML = `<div class="hint" style="margin-bottom:4px">🔒 Private — not shown to the client</div><div><span>Product cost</span><span>${money(prod)}</span></div><div><span>Labour cost</span><span>${money(lab)}</span></div>
    <div><b>Profit on this job</b><b style="color:${prof >= 0 ? 'var(--good)' : 'var(--bad)'}">${money(prof)}</b></div>`;
}
function carLookup() {
  const p = plate($('#fCar').value), H = $('#carHint'); if (p.length < 3) { H.textContent = ''; return; }
  const prev = [...D().sales].reverse().filter(s => plate(s.car) === p); if (!prev.length) { H.textContent = ''; return; }
  const l = prev[0]; if (!$('#fName').value) $('#fName').value = l.name; if (!$('#fPhone').value) $('#fPhone').value = l.phone; if (!$('#fModel').value) $('#fModel').value = l.model;
  const bal = sum(prev, s => Math.max(0, sBal(s)));
  H.innerHTML = `📌 Returning vehicle · ${prev.length} previous visit(s), last on ${nice(l.date)}.` + (bal > 0 ? ` <b>⚠ Previous balance: ${money(bal)}</b>` : ''); readForm();
}
function saveSale(print) {
  readForm(); const d = D();
  if (!draft.car) { toast('Enter the car number', 'err'); $('#fCar').focus(); return; }
  const items = draft.items.filter(i => i.desc.trim() || i.price > 0).map(i => ({ desc: i.desc.trim(), price: i.price, prod: i.prod, lab: i.lab }));
  if (!items.length) { toast('Add at least one service or item', 'err'); return; }
  const noPrice = items.find(i => i.price <= 0); if (noPrice) { toast(`Enter the price for "${noPrice.desc || 'item'}"`, 'err'); return; }
  const sale = { id: 's' + Date.now(), no: d.counter, date: draft.date, car: draft.car, name: draft.name, phone: draft.phone, model: draft.model, items, discount: draft.discount, taxPct: draft.taxPct,
    note: draft.note, status: draft.status, staff: draft.staff, payments: [], created: new Date().toISOString() };
  if (draft.advance > sTotal(sale) + .01) { toast('Advance cannot be more than the bill total', 'err'); return; }
  d.counter++;
  if (draft.advance > 0) sale.payments.push({ date: draft.date, amount: draft.advance, method: draft.method, note: 'Advance' });
  d.sales.push(sale); if (draft.booking) { const b = d.bookings.find(x => x.id === draft.booking); if (b) b.status = 'Completed'; }
  logAct(`Created ${inv(sale.no)} for ${sale.car} (${money(sTotal(sale))})`); save(); draft = null; toast(`${inv(sale.no)} saved`); go('invoices'); if (print) printInvoice(sale.id);
}

/* ================= INVOICES ================= */
let sf = { q: '', from: '', to: '', pay: '', job: '' };
PAGES.invoices = () => {
  $('#view').innerHTML = phead('Invoices', 'Search, filter, print and collect payments', `<button class="btn ghost" id="sCsv">${ic('download', 16)} Export CSV</button><button class="btn" onclick="go('billing')">${ic('plus', 16)} New bill</button>`) + `
  <div class="card"><div class="tools"><div class="grow"><label>Search</label><input id="sq" placeholder="Car no, name, phone, invoice no…" value="${esc(sf.q)}"></div>
    <div><label>From</label><input id="sfrom" type="date" value="${sf.from}"></div><div><label>To</label><input id="sto" type="date" value="${sf.to}"></div>
    <div><label>Payment</label><select id="spay">${opts([['', 'All'], ['paid', 'Paid'], ['part', 'Partial'], ['unpaid', 'Unpaid']], sf.pay)}</select></div>
    <div><label>Job status</label><select id="sjob">${opts([['', 'All'], ...STATUSES], sf.job)}</select></div>
    <div style="min-width:0"><label>&nbsp;</label><button class="btn ghost" id="sToday">Today</button></div></div><div id="salesList"></div></div>`;
  const upd = () => { sf = { q: $('#sq').value, from: $('#sfrom').value, to: $('#sto').value, pay: $('#spay').value, job: $('#sjob').value }; renderInvoices(); };
  ['sq', 'sfrom', 'sto', 'spay', 'sjob'].forEach(i => $('#' + i).oninput = upd);
  $('#sToday').onclick = () => { $('#sfrom').value = $('#sto').value = today(); upd(); };
  $('#sCsv').onclick = () => { const L = filteredSales(); dl(`${BRANDS[S.B].name}-invoices.csv`, csvText([['Invoice', 'Date', 'Car', 'Customer', 'Phone', 'Total', 'Paid', 'Balance', 'Product cost', 'Labour cost', 'Profit', 'Job status'], ...L.map(({ s }) => [inv(s.no), s.date, s.car, s.name, s.phone, sTotal(s), sPaid(s), sBal(s), sProd(s), sLab(s), sProfit(s), s.status])]), 'text/csv'); };
  renderInvoices();
};
function filteredSales() {
  const q = sf.q.toLowerCase().replace(/\s/g, '');
  return [...D().sales].reverse().filter(s => {
    if (sf.from && s.date < sf.from) return false; if (sf.to && s.date > sf.to) return false;
    if (sf.pay && payState(s)[0] !== sf.pay) return false; if (sf.job && s.status !== sf.job) return false;
    return !q || (plate(s.car) + (s.name + s.phone + inv(s.no) + s.model).toLowerCase().replace(/\s/g, '')).toLowerCase().includes(q);
  }).map(s => ({ s, b: S.B }));
}
function renderInvoices() {
  const L = filteredSales();
  $('#salesList').innerHTML = `<div class="muted" style="margin-bottom:8px">${L.length} invoices · Total ${money(sum(L, x => sTotal(x.s)))} · Outstanding ${money(sum(L, x => Math.max(0, sBal(x.s))))}</div>` + salesTable(L.slice(0, 200)) + (L.length > 200 ? '<div class="muted" style="padding:10px">Showing the latest 200 — narrow the filters to see more.</div>' : '');
}

/* ================= JOB BOARD ================= */
PAGES.jobs = () => {
  const d = D(), cut = addDays(today(), -7);
  $('#view').innerHTML = phead('Job Board', 'Drag cards between columns or use the action buttons', `<button class="btn" onclick="go('billing')">${ic('plus', 16)} New bill</button>`) +
    `<div class="kan">${STATUSES.map(st => {
      const all = d.sales.filter(s => s.status === st && (st !== 'Delivered' || s.date >= cut)).sort((a, b) => a.date < b.date || (a.date === b.date && a.no < b.no) ? 1 : -1), L = all.slice(0, st === 'Delivered' ? 6 : 30), nx = STATUSES[STATUSES.indexOf(st) + 1];
      return `<div class="kcol" data-st="${st}"><h4><span>${st}</span><span class="chip ${cssId(st)}">${all.length}</span></h4>${L.map(s => `<div class="kcard" draggable="true" data-id="${s.id}">
        <div style="display:flex;justify-content:space-between"><b>${esc(s.car)}</b><span class="muted">${inv(s.no)}</span></div><div class="muted">${esc(s.model)}</div>
        <div style="margin-top:6px;font-size:13px">${esc(s.items.map(i => i.desc).join(', '))}</div>
        <div class="meta">${payChip(s)}<span class="muted">${esc(staffName(d, s.staff))}</span></div>
        <div class="meta"><b>${money(sTotal(s))}</b><span>${sBal(s) > 0 ? `<button class="btn ghost sm" onclick="payModal('${s.id}')">Receive</button> ` : ''}${nx ? `<button class="btn sm" data-next="${s.id}">${nx === 'Delivered' ? 'Deliver' : '→ ' + nx}</button>` : ''}</span></div></div>`).join('') || '<div class="muted" style="padding:10px">Empty</div>'}${all.length > L.length ? `<button class="btn ghost sm" style="width:100%" onclick="sf.job='${st}';go('invoices')">View all ${all.length} in Invoices</button>` : ''}</div>`;
    }).join('')}</div>`;
  const move = (id, st) => { const s = d.sales.find(x => x.id === id); if (s && s.status !== st) { s.status = st; logAct(`${inv(s.no)} moved to ${st}`); save(); toast(`${inv(s.no)} → ${st}`); refresh(); } };
  $$('[data-next]').forEach(b => b.onclick = () => { const s = d.sales.find(x => x.id === b.dataset.next); move(s.id, STATUSES[STATUSES.indexOf(s.status) + 1]); });
  $$('.kcard').forEach(c => c.ondragstart = e => e.dataTransfer.setData('text/plain', c.dataset.id));
  $$('.kcol').forEach(col => {
    col.ondragover = e => { e.preventDefault(); col.classList.add('over'); }; col.ondragleave = () => col.classList.remove('over');
    col.ondrop = e => { e.preventDefault(); col.classList.remove('over'); move(e.dataTransfer.getData('text/plain'), col.dataset.st); };
  });
};

