const BOOK_STATUS = ['Scheduled', 'Completed', 'Cancelled'];
let bkTab = 'upcoming';
function bookingForm(b) {
  const d = D();
  formModal({
    title: b ? 'Edit appointment' : 'New appointment', saveLabel: 'Save',
    fields: [{ k: 'date', label: 'Date', type: 'date', req: true, def: today() }, { k: 'time', label: 'Time', type: 'time', def: '10:00' }, { k: 'car', label: 'Car number', req: true }, { k: 'model', label: 'Car model' },
      { k: 'name', label: 'Customer name' }, { k: 'phone', label: 'Phone' }, { k: 'service', label: 'Service', wide: true, ph: 'e.g. Ceramic Coating' }, { k: 'status', label: 'Status', type: 'select', options: BOOK_STATUS }, { k: 'note', label: 'Note' }],
    values: b || {}, onSave: o => { o.car = o.car.toUpperCase(); if (b) Object.assign(b, o); else d.bookings.push({ id: 'b' + Date.now(), ...o, status: o.status || 'Scheduled' }); save(); toast('Appointment saved'); refresh(); }
  });
}
PAGES.bookings = () => {
  const d = D(), t = today(); let L = [...d.bookings];
  if (bkTab === 'upcoming') L = L.filter(b => b.date >= t && b.status === 'Scheduled').sort((a, b) => (a.date + a.time) < (b.date + b.time) ? -1 : 1);
  else if (bkTab === 'past') L = L.filter(b => b.date < t || b.status !== 'Scheduled').sort((a, b) => a.date < b.date ? 1 : -1);
  $('#view').innerHTML = phead('Appointments', 'Schedule customer visits and convert them into bills', `<button class="btn" id="bkNew">${ic('plus', 16)} New appointment</button>`) + `
  <div class="card"><div class="tools"><div class="tabs" id="bkTabs">${['upcoming', 'past', 'all'].map(x => `<button data-t="${x}" class="${x === bkTab ? 'on' : ''}">${cap(x)}</button>`).join('')}</div></div>
  ${L.length ? `<div class="tw"><table><thead><tr><th>Date & time</th><th>Vehicle</th><th>Customer</th><th>Service</th><th>Status</th><th></th></tr></thead><tbody>${L.map(b => `<tr><td class="nowrap"><b>${nice(b.date)}</b><small>${esc(b.time)}${b.date === t ? ' · Today' : ''}</small></td>
    <td><b>${esc(b.car)}</b><small>${esc(b.model)}</small></td><td>${esc(b.name) || '—'}<small>${esc(b.phone)}</small></td><td>${esc(b.service)}<small>${esc(b.note)}</small></td><td><span class="chip ${b.status}">${b.status}</span></td>
    <td class="nowrap r">${b.status === 'Scheduled' ? `<button class="btn sm" data-bill="${b.id}">Create bill</button> ` : ''}<button class="btn ghost sm icon" data-edit="${b.id}">${ic('edit', 14)}</button> <button class="btn danger sm icon" data-del="${b.id}">${ic('trash', 14)}</button></td></tr>`).join('')}</tbody></table></div>` : empty('calendar', 'No appointments', 'Create one to see it here.')}</div>`;
  $('#bkNew').onclick = () => bookingForm(); $('#bkTabs').onclick = e => { const b = e.target.closest('button'); if (b) { bkTab = b.dataset.t; PAGES.bookings(); } };
  $$('[data-edit]').forEach(b => b.onclick = () => bookingForm(d.bookings.find(x => x.id === b.dataset.edit)));
  $$('[data-del]').forEach(b => b.onclick = () => confirmBox('Delete this appointment?', () => { d.bookings = d.bookings.filter(x => x.id !== b.dataset.del); save(); refresh(); }));
  $$('[data-bill]').forEach(b => b.onclick = () => {
    const bk = d.bookings.find(x => x.id === b.dataset.bill), sv = d.services.find(x => x.name.toLowerCase() === (bk.service || '').toLowerCase());
    draft = newDraft(); Object.assign(draft, { car: bk.car, name: bk.name, phone: bk.phone, model: bk.model, booking: bk.id }); if (bk.service) draft.items = [{ desc: sv ? sv.name : bk.service, price: 0, prod: 0, lab: 0, hint: sv }]; go('billing');
  });
};

