PAGES.inventory = () => {
  const d = D(), val = sum(d.products, p => p.qty * p.cost), low = d.products.filter(p => p.qty <= p.min).length;
  $('#view').innerHTML = phead('Inventory', 'Track chemicals, coatings and consumables', `<button class="btn" id="pNew">${ic('plus', 16)} New product</button>`) +
    `<div class="grid" style="margin-bottom:14px">${kpi('Products', d.products.length, { icon: 'box' })}${kpi('Stock value', money(val), { icon: 'cash', tone: 'good' })}${kpi('Low stock items', low, { icon: 'alert', tone: low ? 'bad' : '' })}</div><div class="card">
  ${d.products.length ? `<div class="tw"><table><thead><tr><th>Product</th><th class="r">In stock</th><th class="r">Unit cost</th><th class="r">Value</th><th>Status</th><th></th></tr></thead><tbody>
  ${d.products.map(p => `<tr><td><b>${esc(p.name)}</b></td><td class="r">${p.qty} ${esc(p.unit)}</td><td class="r">${money(p.cost)}</td><td class="r">${money(p.qty * p.cost)}</td><td>${p.qty <= p.min ? '<span class="chip low">Low stock</span>' : '<span class="chip ok">OK</span>'}</td>
  <td class="nowrap r"><button class="btn soft sm" data-adj="${p.id}">Adjust stock</button> <button class="btn ghost sm icon" data-e="${p.id}">${ic('edit', 14)}</button> <button class="btn danger sm icon" data-d="${p.id}">${ic('trash', 14)}</button></td></tr>`).join('')}</tbody></table></div>` : empty('box', 'No products yet', 'Add your consumables to receive low-stock alerts.')}</div>`;
  $('#pNew').onclick = () => productForm(); $$('[data-e]').forEach(b => b.onclick = () => productForm(d.products.find(x => x.id === b.dataset.e)));
  $$('[data-d]').forEach(b => b.onclick = () => confirmBox('Delete this product?', () => { d.products = d.products.filter(x => x.id !== b.dataset.d); save(); refresh(); }));
  $$('[data-adj]').forEach(b => b.onclick = () => { const p = d.products.find(x => x.id === b.dataset.adj);
    formModal({ title: 'Adjust stock · ' + esc(p.name), sub: `Currently ${p.qty} ${esc(p.unit)}`, fields: [{ k: 'type', label: 'Action', type: 'select', options: ['Stock in (purchase)', 'Stock out (used)'] }, { k: 'qty', label: 'Quantity', type: 'number', req: true, pos: true }],
      onSave: o => { p.qty = Math.max(0, p.qty + (o.type.startsWith('Stock in') ? o.qty : -o.qty)); save(); toast('Stock updated'); refresh(); } }); });
};

/* ================= TEAM ================= */
function staffForm(m) {
  formModal({ title: m ? 'Edit team member' : 'New team member', fields: [{ k: 'name', label: 'Full name', req: true }, { k: 'role', label: 'Role', ph: 'Detailer, Painter…' }, { k: 'phone', label: 'Phone' }, { k: 'salary', label: 'Monthly salary (Rs)', type: 'number' }],
    values: m || {}, onSave: o => { if (m) Object.assign(m, o); else D().staff.push({ id: 'st' + Date.now(), ...o }); save(); toast('Saved'); refresh(); } });
}
PAGES.staff = () => {
  const d = D(), t = today(), ms = monthStart(t);
  $('#view').innerHTML = phead('Team', 'Staff, salaries and job performance this month', `<button class="btn" id="stNew">${ic('plus', 16)} Add member</button>`) + `<div class="card">
  ${d.staff.length ? `<div class="tw"><table><thead><tr><th>Name</th><th>Role</th><th class="r">Salary</th><th class="r">Jobs (month)</th><th class="r">Revenue handled</th><th></th></tr></thead><tbody>
  ${d.staff.map(m => { const J = d.sales.filter(s => s.staff === m.id && s.date >= ms); return `<tr><td><b>${esc(m.name)}</b><small>${esc(m.phone)}</small></td><td>${esc(m.role)}</td><td class="r">${money(m.salary)}</td><td class="r">${J.length}</td><td class="r">${money(sum(J, sNet))}</td>
  <td class="nowrap r"><button class="btn soft sm" data-pay="${m.id}">Pay salary</button> <button class="btn ghost sm icon" data-e="${m.id}">${ic('edit', 14)}</button> <button class="btn danger sm icon" data-d="${m.id}">${ic('trash', 14)}</button></td></tr>`; }).join('')}</tbody></table></div>` : empty('users', 'No team members', 'Add staff to assign jobs and track performance.')}</div>`;
  $('#stNew').onclick = () => staffForm(); $$('[data-e]').forEach(b => b.onclick = () => staffForm(d.staff.find(x => x.id === b.dataset.e)));
  $$('[data-d]').forEach(b => b.onclick = () => confirmBox('Remove this team member?', () => { d.staff = d.staff.filter(x => x.id !== b.dataset.d); save(); refresh(); }, 'Remove'));
  $$('[data-pay]').forEach(b => b.onclick = () => { const m = d.staff.find(x => x.id === b.dataset.pay);
    confirmBox(`Record salary of <b>${money(m.salary)}</b> for ${esc(m.name)} as today's expense?`, () => { d.expenses.push({ id: 'e' + Date.now(), date: today(), cat: 'Salary', note: 'Salary – ' + m.name, amount: m.salary }); logAct(`Salary paid: ${m.name}`); save(); toast('Salary recorded in expenses'); }, 'Record'); });
};

/* ================= EXPENSES ================= */
let ex = { from: monthStart(today()), to: today() };
PAGES.expenses = () => {
  $('#view').innerHTML = phead('Expenses', 'Record daily studio costs and see where money goes') + `
  <div class="card"><h3>Add expense</h3><div class="row" style="align-items:flex-end"><div style="max-width:170px"><label>Date</label><input id="eD" type="date" value="${today()}"></div>
    <div><label>Category</label><select id="eC">${opts(EXP_CATS)}</select></div><div style="flex:2"><label>Details</label><input id="eN" placeholder="e.g. Shampoo 5 litre, Ali's advance"></div>
    <div><label>Amount (Rs)</label><input id="eA" type="number" min="0"></div><div style="flex:0;min-width:120px"><button class="btn" id="eAdd" style="width:100%">${ic('plus', 16)} Add</button></div></div></div>
  <div class="cols"><div class="card"><div class="tools"><div><label>From</label><input id="exF" type="date" value="${ex.from}"></div><div><label>To</label><input id="exT" type="date" value="${ex.to}"></div></div><div id="expList"></div></div>
    <div class="card"><h3>By category</h3><div id="expCat"></div></div></div>`;
  $('#eAdd').onclick = () => { const a = num($('#eA').value); if (a <= 0) return toast('Enter an amount', 'err');
    D().expenses.push({ id: 'e' + Date.now(), date: $('#eD').value || today(), cat: $('#eC').value, note: $('#eN').value.trim(), amount: a }); save(); toast('Expense added'); $('#eA').value = ''; $('#eN').value = ''; renderExp(); };
  $('#exF').onchange = $('#exT').onchange = () => { ex.from = $('#exF').value; ex.to = $('#exT').value; renderExp(); }; renderExp();
};
function renderExp() {
  const L = D().expenses.filter(e => e.date >= ex.from && e.date <= ex.to).sort((a, b) => a.date < b.date ? 1 : -1), tot = sum(L, e => e.amount), cat = {};
  L.forEach(e => cat[e.cat] = (cat[e.cat] || 0) + e.amount);
  $('#expList').innerHTML = `<div class="ch"><span class="muted">${L.length} entries</span><b>Total ${money(tot)}</b></div>` + (L.length ? `<div class="tw"><table><thead><tr><th>Date</th><th>Category</th><th>Details</th><th class="r">Amount</th><th></th></tr></thead><tbody>
    ${L.slice(0, 300).map(e => `<tr><td class="nowrap">${nice(e.date)}</td><td>${esc(e.cat)}</td><td>${esc(e.note)}</td><td class="r">${money(e.amount)}</td><td class="r"><button class="btn danger sm icon" onclick="delExp('${e.id}')">${ic('trash', 14)}</button></td></tr>`).join('')}</tbody></table></div>` : empty('wallet', 'No expenses in this range'));
  $('#expCat').innerHTML = donut(Object.entries(cat).sort((a, b) => b[1] - a[1]).map(([k, v], i) => ({ label: k, value: v, color: PALETTE[i % PALETTE.length] })), 'Expenses');
}
function delExp(id) { confirmBox('Delete this expense?', () => { D().expenses = D().expenses.filter(e => e.id !== id); save(); renderExp(); }); }

/* ================= REPORTS ================= */
let rp = 'daily', ra = today();
PAGES.reports = () => {
  const d = D(), [f, t] = periodRange(rp, ra), s = stats(d, f, t), bk = buckets(d, rp, ra), title = rp === 'daily' ? nice(ra) : nice(f) + ' → ' + nice(t);
  const sales = d.sales.filter(x => x.date >= f && x.date <= t), svc = {}, pm = {}, stf = {}, cat = {};
  sales.forEach(x => { x.items.forEach(i => { const k = (i.desc || '—').trim(), o = svc[k] = svc[k] || { n: 0, r: 0 }; o.n++; o.r += i.price; }); const sn = staffName(d, x.staff) || 'Unassigned', o = stf[sn] = stf[sn] || { n: 0, r: 0 }; o.n++; o.r += sNet(x); });
  d.sales.forEach(x => x.payments.forEach(p => { if (p.date >= f && p.date <= t) pm[p.method] = (pm[p.method] || 0) + p.amount; }));
  d.expenses.filter(e => e.date >= f && e.date <= t).forEach(e => cat[e.cat] = (cat[e.cat] || 0) + e.amount);
  const sl = Object.entries(svc).sort((a, b) => b[1].r - a[1].r).slice(0, 8);
  $('#view').innerHTML = phead('Reports', 'Daily, weekly and monthly performance', `<button class="btn ghost" id="rPrint">${ic('print', 16)} Print</button><button class="btn ghost" id="rCsv">${ic('download', 16)} Export CSV</button>`) + `
  <div class="tools"><div class="tabs" id="rTabs">${['daily', 'weekly', 'monthly'].map(x => `<button data-p="${x}" class="${x === rp ? 'on' : ''}">${cap(x)}</button>`).join('')}</div>
    <div style="max-width:170px"><label>Pick a date</label><input id="rDate" type="date" value="${ra}"></div><button class="btn ghost sm" id="rPrev">${ic('back', 14)} Previous</button><button class="btn ghost sm" id="rNext">Next ${ic('arrow', 14)}</button></div>
  <h3 style="margin-bottom:12px">${title}</h3>
  <div class="grid k4">${kpi('Revenue', money(s.revenue), { icon: 'trend', sub: s.count + ' bills' })}${kpi('Cash received', money(s.cash), { icon: 'cash', tone: 'good' })}${kpi('Product cost', money(s.prod), { icon: 'box' })}${kpi('Labour cost', money(s.lab), { icon: 'users' })}
    ${kpi('Gross profit', money(s.gross), { icon: 'chart', tone: s.gross >= 0 ? 'good' : 'bad' })}${kpi('Expenses', money(s.exp), { icon: 'wallet', tone: 'bad' })}${kpi('Net profit', money(s.net), { icon: 'trend', tone: s.net >= 0 ? 'good' : 'bad', sub: s.margin.toFixed(0) + '% margin' })}${kpi('New balance due', money(s.pending), { icon: 'alert', tone: 'warn' })}</div>
  <div class="card" style="margin-top:14px"><div class="ch"><h3>Trend</h3>${legend([{ name: 'Revenue', color: 'var(--accent)' }, { name: 'Net profit', color: '#2fd08a' }])}</div>
    ${barSvg(bk.map(b => b.l), [{ name: 'Revenue', color: 'var(--accent)', data: bk.map(b => b.s.revenue) }, { name: 'Net profit', color: '#2fd08a', data: bk.map(b => b.s.net) }])}</div>
  <div class="cols eq"><div class="card"><h3>Top services</h3>${sl.length ? `<table>${sl.map(([k, v]) => `<tr><td>${esc(k)}</td><td class="muted">${v.n}×</td><td class="r">${money(v.r)}</td></tr>`).join('')}</table>` : '<div class="muted">No data</div>'}</div>
    <div class="card"><h3>Payments by method</h3>${donut(Object.entries(pm).map(([k, v], i) => ({ label: k, value: v, color: PALETTE[i % PALETTE.length] })), 'Collected')}</div></div>
  <div class="cols eq"><div class="card"><h3>Expenses by category</h3>${donut(Object.entries(cat).map(([k, v], i) => ({ label: k, value: v, color: PALETTE[i % PALETTE.length] })), 'Expenses')}</div>
    <div class="card"><h3>Team performance</h3>${Object.keys(stf).length ? `<table>${Object.entries(stf).sort((a, b) => b[1].r - a[1].r).map(([k, v]) => `<tr><td>${esc(k)}</td><td class="muted">${v.n} job${v.n > 1 ? 's' : ''}</td><td class="r">${money(v.r)}</td></tr>`).join('')}</table>` : '<div class="muted">No data</div>'}</div></div>`;
  $('#rTabs').onclick = e => { const b = e.target.closest('button'); if (b) { rp = b.dataset.p; PAGES.reports(); } };
  $('#rDate').onchange = () => { ra = $('#rDate').value || today(); PAGES.reports(); };
  const mv = k => { ra = rp === 'monthly' ? dstr(new Date(pd(ra).getFullYear(), pd(ra).getMonth() + k, 1)) : addDays(ra, k * (rp === 'weekly' ? 7 : 1)); PAGES.reports(); };
  $('#rPrev').onclick = () => mv(-1); $('#rNext').onclick = () => mv(1);
  $('#rCsv').onclick = () => dl(`${BRANDS[S.B].name}-${rp}-report.csv`, csvText([['Period', 'Bills', 'Revenue', 'Cash received', 'Product cost', 'Labour cost', 'Gross profit', 'Expenses', 'Net profit'], ...bk.map(b => [b.l, b.s.count, b.s.revenue, b.s.cash, b.s.prod, b.s.lab, b.s.gross, b.s.exp, b.s.net])]), 'text/csv');
  $('#rPrint').onclick = () => printHTML(`<div class="inv report"><div class="band" style="--ib:${BRANDS[S.B].color};background:${BRANDS[S.B].color}"></div><div class="in"><h1>${BRANDS[S.B].name} — ${cap(rp)} report</h1><div>${title}</div>
    <h3>Profit & loss</h3><table><tbody>${[['Revenue', s.revenue], ['Product cost', -s.prod], ['Labour cost', -s.lab], ['Gross profit', s.gross], ['Expenses', -s.exp], ['Net profit', s.net]].map(([k, v]) => `<tr><td>${k}</td><td style="text-align:right">${money(v)}</td></tr>`).join('')}</tbody></table>
    <h3>Collections</h3><table><tbody><tr><td>Cash received</td><td style="text-align:right">${money(s.cash)}</td></tr><tr><td>New balance due</td><td style="text-align:right">${money(s.pending)}</td></tr><tr><td>Bills</td><td style="text-align:right">${s.count}</td></tr></tbody></table></div></div>`);
};

/* ================= SETTINGS ================= */
PAGES.settings = () => {
  const d = D(), p = d.profile, hasDemo = [d.sales, d.expenses, d.staff, d.bookings, d.products].some(a => a.some(x => x.demo));
  $('#view').innerHTML = phead('Settings', 'Business profile, invoice options, access and data') + `<div class="cols eq" style="margin-top:0">
  <div class="card"><h3>Invoice & business profile</h3><div class="fgrid"><div><label>Phone</label><input id="sPh" value="${esc(p.phone)}"></div><div><label>Default tax %</label><input id="sTax" type="number" min="0" step="any" value="${p.tax || 0}"></div>
    <div class="wide"><label>Address</label><textarea id="sAd" rows="2">${esc(p.address)}</textarea></div><div class="wide"><label>Invoice footer message</label><input id="sFt" value="${esc(p.footer)}"></div>
    <div class="wide"><label>Paper size</label><select id="sPaper">${opts([['A4', 'A4 (standard printer)'], ['thermal', 'Thermal receipt (80 mm)']], p.paper)}</select></div></div><button class="btn" id="sSave" style="margin-top:14px">Save profile</button></div>
  <div class="stack"><div class="card"><h3>Login credentials</h3><div class="fgrid"><div><label>Username</label><input id="sU" value="${esc(d.user)}"></div><div><label>New password</label><input id="sP" type="password" placeholder="Leave blank to keep"></div></div><button class="btn" id="sCred" style="margin-top:14px">Update credentials</button></div>
  <div class="card"><h3>Data & backup</h3><div class="muted" style="margin-bottom:12px">Data is stored in this browser. Download a backup regularly.</div>
    <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn ghost" id="bk">${ic('download', 16)} Download backup</button><label class="btn ghost" style="margin:0;cursor:pointer">${ic('upload', 16)} Restore<input type="file" id="rs" accept=".json" class="hidden"></label>
    ${hasDemo ? `<button class="btn danger" id="demoClr">Remove demo data</button>` : `<button class="btn soft" id="demoLoad">Load demo data</button>`}</div></div></div></div>`;
  $('#sSave').onclick = () => { p.phone = $('#sPh').value; p.address = $('#sAd').value; p.footer = $('#sFt').value; p.tax = num($('#sTax').value); p.paper = $('#sPaper').value; save(); toast('Profile saved'); };
  $('#sCred').onclick = () => { const u = $('#sU').value.trim(); if (!u) return toast('Username is required', 'err'); d.user = u; if ($('#sP').value) d.pass = $('#sP').value; save(); toast('Credentials updated'); };
  $('#bk').onclick = () => dl(`${BRANDS[S.B].name}-backup-${today()}.json`, JSON.stringify(d), 'application/json');
  $('#rs').onchange = e => { const f = e.target.files[0]; if (!f) return; const r = new FileReader(); r.onload = () => { try { const x = JSON.parse(r.result); if (!x.sales || !x.expenses) throw 0; confirmBox('Current data of this brand will be replaced by the backup.', () => { DB.brands[S.B] = x; save(); DB = loadDB(); toast('Backup restored'); refresh(); }, 'Restore'); } catch (_) { toast('Invalid backup file', 'err'); } }; r.readAsText(f); };
  if ($('#demoLoad')) $('#demoLoad').onclick = () => { seedDemo(S.B); save(); toast('Demo data loaded'); refresh(); };
  if ($('#demoClr')) $('#demoClr').onclick = () => confirmBox('Only demo records will be removed. Your real data stays.', () => { clearDemo(S.B); save(); toast('Demo data removed'); refresh(); }, 'Remove');
};
